/// Appends two vectors of copyable elements, returning a new vector
/// whose elements are first all of `v1` in order, then all of `v2` in order.
fn append_vectors<T: Copy>(v1: &Vec<T>, v2: &Vec<T>) -> Vec<T> {
    // Reserve exactly the needed capacity up front
    let mut result = Vec::with_capacity(v1.len() + v2.len());
    // Copy all of v1
    for &item in v1.iter() {
        result.push(item);
    }
    // Copy all of v2
    for &item in v2.iter() {
        result.push(item);
    }
    result
}

/// Given a non‐empty vector `first` and another vector `second`,
/// returns a new vector consisting of all elements of `first` except its last,
/// followed by all elements of `second`.
fn replace_last_element(first: &Vec<i32>, second: &Vec<i32>) -> Vec<i32> {
    // We assume `first` is non‐empty, so `first.len() >= 1`
    let cut = first.len() - 1;
    // Build a small prefix vector containing all but the last element of `first`
    let prefix = first[..cut].to_vec();
    // Now concatenate that prefix with `second` using our helper
    append_vectors(&prefix, second)
}

